// C++98-style problem demonstration
#include <vector>
#include <algorithm>

void demonstrate_cpp98_issue(std::vector<int>& values) {
    // Ideally, we'd use const_iterator for a read-only find operation
    std::vector<int>::const_iterator const_it = 
        std::find(values.cbegin(), values.cend(), 1983);

    // ... but container::insert requires a non-const iterator.
    // This line would cause a compile error in C++98 because there's
    // no implicit conversion from const_iterator to iterator.
    // values.insert(const_it, 1998); // COMPILE ERROR

    // The C++98 workaround was to use non-const iterators from the start
    std::vector<int>::iterator it = 
        std::find(values.begin(), values.end(), 1983);
    values.insert(it, 1998); // This works, but breaks const-correctness
}
